(()=>{'use strict';const carousel=document.querySelector('.carousel');if(carousel){const slides=[...carousel.querySelectorAll('[data-slide]')],dots=[...carousel.querySelectorAll('[data-slide-to]')],pause=carousel.querySelector('[data-slide-pause]'),announcement=carousel.querySelector('[data-slide-status]');let current=0,paused=matchMedia('(prefers-reduced-motion:reduce)').matches,hover=false;function render(index,announce=false){current=(index+slides.length)%slides.length;slides.forEach((s,i)=>s.hidden=i!==current);dots.forEach((d,i)=>d.setAttribute('aria-current',String(i===current)));if(announce)announcement.textContent=`Slide ${current+1} of ${slides.length}`;}function pauseUI(){pause.textContent=paused?'▶':'Ⅱ';pause.setAttribute('aria-label',paused?'Play slideshow':'Pause slideshow')}carousel.querySelector('[data-slide-prev]').addEventListener('click',()=>{paused=true;pauseUI();render(current-1,true)});carousel.querySelector('[data-slide-next]').addEventListener('click',()=>{paused=true;pauseUI();render(current+1,true)});dots.forEach(d=>d.addEventListener('click',()=>{paused=true;pauseUI();render(Number(d.dataset.slideTo),true)}));pause.addEventListener('click',()=>{paused=!paused;pauseUI()});carousel.addEventListener('mouseenter',()=>hover=true);carousel.addEventListener('mouseleave',()=>hover=false);carousel.addEventListener('focusin',()=>{paused=true;pauseUI()});carousel.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();paused=true;pauseUI();render(current+(e.key==='ArrowRight'?1:-1),true)}});setInterval(()=>{if(!paused&&!hover&&!document.hidden)render(current+1)},8000);pauseUI()}})();
